# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SINIFIM (صَفِّي) — SINIF EŞYALARI VE KIRIK ÇOĞULLAR (الْجَمْعُ)</text>\n  <rect x="20" y="45" width="210" height="95" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">اَلصَّفُّ وَالْمَدْرَسَةُ</text>\n  <text x="125" y="88" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">Sınıf ve Okul Donanımı</text>\n  <text x="125" y="108" text-anchor="middle" font-size="10.5" fill="#1d4ed8">سَبُّورَةٌ (Tahta) · مِمْحَاةٌ (Silgi)</text>\n  <text x="125" y="126" text-anchor="middle" font-size="10.5" fill="#1d4ed8">طَاوِلَةٌ (Masa) · كُرْسِيٌّ (Sandalye)</text>\n  <rect x="245" y="45" width="210" height="95" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">أَدَوَاتُ الطَّالِبِ</text>\n  <text x="350" y="88" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">Öğrenci Ders Araçları</text>\n  <text x="350" y="108" text-anchor="middle" font-size="10.5" fill="#166534">حَقِيبَةٌ (Çanta) · مِقْلَمَةٌ (Kalemlik)</text>\n  <text x="350" y="126" text-anchor="middle" font-size="10.5" fill="#166534">خَرِيطَةٌ (Harita) · سَاعَةٌ (Saat)</text>\n  <rect x="470" y="45" width="210" height="95" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">الْمُفْرَدُ وَالْجَمْعُ (Tekil - Çoğul)</text>\n  <text x="575" y="90" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">قَلَمٌ ← أَقْلَامٌ (Kalemler)</text>\n  <text x="575" y="108" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">كِتَابٌ ← كُتُبٌ (Kitaplar)</text>\n  <text x="575" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">دَفْتَرٌ ← دَفَاتِرُ (Defterler)</text>\n  <rect x="20" y="152" width="320" height="92" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="180" y="174" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">مَا هٰذَا / مَا هٰذِهِ؟ (BU NEDİR?)</text>\n  <text x="35" y="198" font-size="11" font-weight="bold" fill="#581c87">• مَا هٰذَا؟ ← هٰذَا قَلَمٌ / هٰذَا كُرْسِيٌّ (Müzekker)</text>\n  <text x="35" y="220" font-size="11" font-weight="bold" fill="#581c87">• مَا هٰذِهِ؟ ← هٰذِهِ سَبُّورَةٌ / هٰذِهِ حَقِيبَةٌ (Müennes)</text>\n  <rect x="360" y="152" width="320" height="92" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="174" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">VECİZ SÖZ VE TEMEL SIFATLAR</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">«اَلْعِلْمُ نُورٌ وَالْجَهْلُ ظَلَامٌ» (İlim nurdur, cehalet karanlıktır)</text>\n  <text x="520" y="220" text-anchor="middle" font-size="10.5" fill="#7f1d1d">مُجْتَهِدٌ (Çalışkan) · جَمِيلٌ (Güzel) · نَظِيفٌ (Temiz)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SINIFTA KONUM (أَيْنَ؟) VE RENKLER (مَا لَوْنُ ...؟)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">HARF-İ CERLER VE MEKÂN ZARFLARI</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">• فِي الصَّفِّ سَبُّورَةٌ. (Sınıfta bir tahta vardır.)</text>\n  <text x="35" y="118" font-size="11" font-weight="bold" fill="#1e3a8a">• الْكِتَابُ عَلَى / فَوْقَ الطَّاوِلَةِ. (Kitap masanın üstündedir.)</text>\n  <text x="35" y="142" font-size="11" font-weight="bold" fill="#1e3a8a">• الْحَقِيبَةُ تَحْتَ الْمَكْتَبِ. (Çanta sıranın altındadır.)</text>\n  <text x="35" y="166" font-size="11" font-weight="bold" fill="#1e3a8a">• الْمُعَلِّمُ أَمَامَ السَّبُّورَةِ. (Öğretmen tahtanın önündedir.)</text>\n  <text x="35" y="190" font-size="11" font-weight="bold" fill="#1e3a8a">• الطَّالِبُ خَلْفَ الْمَكْتَبِ. (Öğrenci sıranın arkasındadır.)</text>\n  <text x="35" y="216" font-size="10.5" font-weight="bold" fill="#b91c1c">• قَرِيبٌ مِنْ (yakın) ↔ بَعِيدٌ عَنْ (uzak)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">الْأَلْوَانُ (TEMEL RENKLER)</text>\n  <text x="378" y="96" font-size="11" font-weight="bold" fill="#dc2626">• أَحْمَرُ (Kırmızı)</text>\n  <text x="530" y="96" font-size="11" font-weight="bold" fill="#2563eb">• أَزْرَقُ (Mavi)</text>\n  <text x="378" y="122" font-size="11" font-weight="bold" fill="#ca8a04">• أَصْفَرُ (Sarı)</text>\n  <text x="530" y="122" font-size="11" font-weight="bold" fill="#16a34a">• أَخْضَرُ (Yeşil)</text>\n  <text x="378" y="148" font-size="11" font-weight="bold" fill="#0f172a">• أَسْوَدُ (Siyah)</text>\n  <text x="530" y="148" font-size="11" font-weight="bold" fill="#475569">• أَبْيَضُ (Beyaz)</text>\n  <rect x="375" y="168" width="290" height="58" rx="8" fill="#ffffff" stroke="#86efac" stroke-width="1.5"/>\n  <text x="388" y="190" font-size="11" font-weight="bold" fill="#14532d">Soru: مَا لَوْنُ الْقَلَمِ؟ (Kalemin rengi nedir?)</text>\n  <text x="388" y="212" font-size="11" font-weight="bold" fill="#166534">Cevap: لَوْنُ الْقَلَمِ أَزْرَقُ. (Kalemin rengi mavidir.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SINIF İÇİ EMİR FİİLLERİ, SAYILAR (1-12) VE SOSYAL İFADELER</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">EMİR FİİLLERİ (Müzekker / Müennes)</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#78350f">• اُدْخُلْ / اُدْخُلِي : İçeri gir!</text>\n  <text x="35" y="120" font-size="11" font-weight="bold" fill="#78350f">• اُخْرُجْ / اُخْرُجِي : Dışarı çık!</text>\n  <text x="35" y="144" font-size="11" font-weight="bold" fill="#78350f">• اِجْلِسْ / اِجْلِسِي : Otur!</text>\n  <text x="35" y="168" font-size="11" font-weight="bold" fill="#78350f">• قُمْ / قُومِي : Ayağa kalk!</text>\n  <text x="35" y="198" font-size="11" font-weight="bold" fill="#b91c1c">• مِنْ فَضْلِكَ / فَضْلِكِ : Lütfen!</text>\n  <text x="35" y="220" font-size="11" font-weight="bold" fill="#b91c1c">• آسِفٌ (E) / آسِفَةٌ (K) : Özür dilerim / Üzgünüm</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">الْأَعْدَادُ (1\'DEN 12\'YE KADAR SAYILAR)</text>\n  <text x="378" y="96" font-size="10.5" font-weight="bold" fill="#581c87">1: وَاحِدٌ · 2: اِثْنَانِ · 3: ثَلَاثَةٌ · 4: أَرْبَعَةٌ</text>\n  <text x="378" y="120" font-size="10.5" font-weight="bold" fill="#581c87">5: خَمْسَةٌ · 6: سِتَّةٌ · 7: سَبْعَةٌ · 8: ثَمَانِيَةٌ</text>\n  <text x="378" y="144" font-size="10.5" font-weight="bold" fill="#581c87">9: تِسْعَةٌ · 10: عَشَرَةٌ · 11: أَحَدَ عَشَرَ · 12: اِثْنَا عَشَرَ</text>\n  <rect x="375" y="164" width="290" height="62" rx="8" fill="#ffffff" stroke="#d8b4fe" stroke-width="1.5"/>\n  <text x="388" y="186" font-size="10.5" font-weight="bold" fill="#6b21a8">Sahiplik: هَلْ عِنْدَكَ قَلَمٌ؟ (Kalemin var mı?)</text>\n  <text x="388" y="204" font-size="10.5" fill="#581c87">+ نَعَمْ، عِنْدِي قَلَمٌ. (Evet, kalemim var.)</text>\n  <text x="388" y="220" font-size="10.5" fill="#581c87">- لَا، مَا عِنْدِي قَلَمٌ. (Hayır, kalemim yok.)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
